(async()=>{const out={};for(const value of ['data:,hello+world','data:,a%20b?c#ignored','data:;charset=UTF-8,%D0%AF','data:;base64,YQ','data:text/plain;base64,YQ==','data:text/plain;base64,Y Q ==','data:badtype,a','data:,100%','data:;base64,Y===']){try{const r=await fetch(value);out[value]=[r.status,r.headers.get('content-type'),await r.text()]}catch(e){out[value]=e.name}}return out})()
